insert into public.curated_recipes
  (title,summary,category,source_name,source_url,suitable_for_elimination,servings,preparation_minutes,ingredients,instructions,attribution_note,phase_note,published)
values
  ('Overnight oats met aardbei en chia','Een rustig low-FODMAP ontbijt voor 1 persoon. vegetarisch, meal-prep.','ontbijt','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-001',true,1,5,E'45 g havermout\n150 ml lactosevrije melk\n75 g aardbeien — in stukjes\n10 g chiazaad\n5 ml pure ahornsiroop — optioneel',E'1. Meng alles behalve de aardbeien in een afsluitbare kom.\n2. Zet minimaal 6 uur in de koelkast.\n3. Voeg de aardbeien vlak voor serveren toe.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Warme havermout met kiwi en walnoot','Een rustig low-FODMAP ontbijt voor 1 persoon. vegetarisch.','ontbijt','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-002',true,1,12,E'45 g havermout\n200 ml lactosevrije melk\n1 stuk kiwi — geschild\n15 g walnoten — grof gehakt\n1 snuf kaneel',E'1. Kook havermout en melk 5–7 minuten zachtjes.\n2. Snijd de kiwi.\n3. Serveer met kiwi, walnoten en kaneel.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Quinoapap met ananas en kokos','Een rustig low-FODMAP ontbijt voor 1 persoon. vegan, glutenvrij.','ontbijt','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-003',true,1,20,E'150 g gekookte quinoa\n150 ml ongezoete amandeldrink — zonder inuline\n100 g verse ananas — blokjes\n5 g kokosrasp\n1 snuf kaneel',E'1. Verwarm quinoa met amandeldrink 8–10 minuten.\n2. Roer de kaneel erdoor.\n3. Serveer met ananas en kokosrasp.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Omelet met spinazie en tomaat','Een rustig low-FODMAP ontbijt voor 1 persoon. vegetarisch, glutenvrij.','ontbijt','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-004',true,1,15,E'2 stuks eieren\n50 g babyspinazie\n75 g tomaat — in blokjes\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\nnaar smaak  zout en zwarte peper',E'1. Verhit de olie en laat spinazie slinken.\n2. Voeg tomaat toe en bak 1 minuut.\n3. Klop eieren los, giet erbij en bak gaar.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Eimuffins met aardappel en bieslook','Een rustig low-FODMAP ontbijt voor 2 personen. vegetarisch, glutenvrij, meal-prep.','ontbijt','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-005',true,2,34,E'4 stuks eieren\n160 g gekookte aardappel — blokjes\n10 g bieslook — fijn\n30 ml lactosevrije melk\n30 g geraspte harde kaas\nnaar smaak  zout en zwarte peper',E'1. Verwarm de oven voor op 180 °C en vet 4 muffinvormen in.\n2. Verdeel aardappel en bieslook over de vormen.\n3. Klop ei met melk, kaas, zout en peper.\n4. Vul de vormen en bak 20–22 minuten.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Boekweitpannenkoeken met aardbeien','Een rustig low-FODMAP ontbijt voor 2 personen. vegetarisch, glutenvrij.','ontbijt','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-006',true,2,22,E'100 g boekweitmeel — gecertificeerd glutenvrij indien nodig\n1 stuk ei\n180 ml lactosevrije melk\n5 g bakpoeder — controleer glutenvrij\n150 g aardbeien\n10 ml pure ahornsiroop',E'1. Klop meel, ei, melk en bakpoeder glad.\n2. Bak kleine pannenkoeken in een licht ingevette pan.\n3. Serveer per persoon met 75 g aardbeien en 5 ml ahornsiroop.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Lactosevrije yoghurtbowl met druiven','Een rustig low-FODMAP ontbijt voor 1 persoon. vegetarisch, glutenvrij.','ontbijt','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-007',true,1,5,E'170 g lactosevrije yoghurt — naturel\n80 g druiven — gehalveerd\n15 g walnoten\n10 g pompoenpitten\n1 snuf kaneel',E'1. Schep de yoghurt in een kom.\n2. Verdeel druiven, walnoten en pompoenpitten erover.\n3. Bestrooi met kaneel.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Hartige havermout met ei en spinazie','Een rustig low-FODMAP ontbijt voor 1 persoon. vegetarisch.','ontbijt','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-008',true,1,15,E'45 g havermout\n220 ml water\n1 stuk ei\n50 g babyspinazie\n10 g groene deel lente-ui — fijn\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\nnaar smaak  zout en zwarte peper',E'1. Kook de havermout met water tot een romige pap.\n2. Bak in de olie het ei en laat spinazie kort slinken.\n3. Schep op de havermout en garneer met groen van lente-ui.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Ontbijttaco’s met roerei','Een rustig low-FODMAP ontbijt voor 2 personen. vegetarisch, glutenvrij.','ontbijt','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-009',true,2,20,E'4 klein maïstortilla’s — controleer dat tarwe, ui en inuline ontbreken\n4 stuks eieren\n100 g tomaat — blokjes\n40 g geraspte harde kaas\n15 g groene deel lente-ui\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\nnaar smaak  zout en zwarte peper',E'1. Verwarm de tortilla’s volgens de verpakking.\n2. Bak zacht roerei in de olie.\n3. Verdeel ei, tomaat, kaas en lente-uigroen over de tortilla’s.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Chiapudding met kiwi en limoen','Een rustig low-FODMAP ontbijt voor 1 persoon. vegan, glutenvrij, meal-prep.','ontbijt','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-010',true,1,5,E'24 g chiazaad\n180 ml ongezoete amandeldrink — zonder inuline\n1 stuk kiwi\n5 ml limoensap\n5 ml pure ahornsiroop — optioneel',E'1. Roer chia, drink, limoensap en ahornsiroop door elkaar.\n2. Roer na 10 minuten opnieuw en koel minimaal 4 uur.\n3. Serveer met gesneden kiwi.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Kip-rijstsalade met komkommer','Een uitgebalanceerde low-FODMAP lunch voor 2 personen. glutenvrij, meal-prep.','lunch','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-011',true,2,30,E'250 g kipfilet\n300 g gekookte basmatirijst — afgekoeld\n150 g komkommer — blokjes\n100 g wortel — linten\n20 ml citroensap\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\n15 g peterselie\nnaar smaak  zout en zwarte peper',E'1. Bak de kip gaar in de helft van de olie en snijd in repen.\n2. Meng rijst, komkommer, wortel en peterselie.\n3. Klop resterende olie met citroensap en meng door de salade.\n4. Verdeel de kip erover.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Tonijn-aardappelsalade','Een uitgebalanceerde low-FODMAP lunch voor 2 personen. glutenvrij, meal-prep.','lunch','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-012',true,2,30,E'400 g vastkokende aardappelen\n145 g tonijn in water — uitgelekt\n120 g komkommer\n150 g sperziebonen\n30 g mayonaise — zonder ui/knoflook\n15 ml citroensap\n10 g bieslook\nnaar smaak  zout en zwarte peper',E'1. Kook aardappelen en bonen afzonderlijk beetgaar en laat afkoelen.\n2. Meng mayonaise, citroen, bieslook, zout en peper.\n3. Schep aardappel, bonen, komkommer en tonijn door de dressing.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Quinoasalade met feta en olijven','Een uitgebalanceerde low-FODMAP lunch voor 2 personen. vegetarisch, glutenvrij, meal-prep.','lunch','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-013',true,2,30,E'300 g gekookte quinoa\n150 g komkommer\n150 g tomaat\n60 g feta\n40 g olijven\n20 ml citroensap\n20 ml olijfolie\n15 g peterselie\nnaar smaak  zout en zwarte peper',E'1. Meng quinoa, komkommer, tomaat, olijven en peterselie.\n2. Klop olie, citroensap, zout en peper.\n3. Schep de dressing erdoor en verkruimel feta erover.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Tofu-rijstbowl met wortel en spinazie','Een uitgebalanceerde low-FODMAP lunch voor 2 personen. vegan, glutenvrij, meal-prep.','lunch','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-014',true,2,30,E'300 g stevige tofu — uitgelekt en in blokjes\n300 g gekookte rijst\n120 g wortel — reepjes\n100 g babyspinazie\n20 ml tamari — glutenvrij, zonder ui/knoflook\n10 ml sesamolie\n10 g sesamzaad',E'1. Bak tofu goudbruin in sesamolie.\n2. Voeg wortel en spinazie toe en roerbak kort.\n3. Roer tamari erdoor.\n4. Serveer met rijst en sesamzaad.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Wortel-gembersoep','Een uitgebalanceerde low-FODMAP lunch voor 4 personen. vegan, glutenvrij, meal-prep.','lunch','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-015',true,4,40,E'600 g wortelen — plakjes\n250 g aardappel — blokjes\n15 g verse gember — geraspt\n30 g groene deel lente-ui\n1000 ml low-FODMAP bouillon — zonder ui/knoflook\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\nnaar smaak  zout en zwarte peper',E'1. Fruit gember en lente-uigroen 2 minuten in olie.\n2. Voeg wortel, aardappel en bouillon toe.\n3. Kook 20 minuten en pureer glad.\n4. Breng op smaak en verdeel in 4 porties.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Aardappel-spinaziesoep met bieslook','Een uitgebalanceerde low-FODMAP lunch voor 4 personen. vegetarisch, glutenvrij, meal-prep.','lunch','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-016',true,4,37,E'600 g aardappelen — blokjes\n200 g babyspinazie\n900 ml low-FODMAP bouillon — zonder ui/knoflook\n100 ml lactosevrije kookroom\n20 g bieslook\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\nnaar smaak  zout en zwarte peper',E'1. Kook aardappel 18 minuten in bouillon.\n2. Voeg spinazie toe en laat slinken.\n3. Pureer met room en bieslook.\n4. Verwarm nog 2 minuten zonder hard te koken.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Gebakken rijst met ei en groenten','Een uitgebalanceerde low-FODMAP lunch voor 2 personen. vegetarisch, glutenvrij.','lunch','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-017',true,2,22,E'350 g gekookte rijst — koud\n2 stuks eieren\n100 g wortel — kleine blokjes\n120 g sperziebonen — stukjes\n20 ml tamari — zonder ui/knoflook\n15 g groene deel lente-ui\n10 ml sesamolie',E'1. Bak wortel en bonen in sesamolie beetgaar.\n2. Schuif opzij, voeg ei toe en roer tot het stolt.\n3. Voeg rijst en tamari toe en bak goed heet.\n4. Garneer met lente-uigroen.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Kalkoen-slawraps','Een uitgebalanceerde low-FODMAP lunch voor 2 personen. glutenvrij.','lunch','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-018',true,2,27,E'250 g kalkoengehakt\n80 g wortel — geraspt\n100 g komkommer — reepjes\n8 grote bladeren kropsla\n15 ml tamari\n10 ml sesamolie\n8 g verse gember — geraspt\n15 g groene deel lente-ui',E'1. Bak kalkoengehakt met gember gaar in sesamolie.\n2. Roer tamari en wortel erdoor en bak 2 minuten.\n3. Vul slabladeren met gehakt en komkommer.\n4. Garneer met lente-uigroen.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Zalm-komkommer-rijstbowl','Een uitgebalanceerde low-FODMAP lunch voor 2 personen. glutenvrij.','lunch','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-019',true,2,27,E'250 g zalmfilet\n300 g gekookte rijst\n160 g komkommer\n100 g wortel\n15 ml tamari\n15 ml limoensap\n10 g sesamzaad',E'1. Bak of stoom de zalm gaar en verdeel in stukken.\n2. Verdeel rijst, komkommer en wortel over kommen.\n3. Meng tamari met limoensap en sprenkel erover.\n4. Voeg zalm en sesam toe.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Rijstnoedelsalade met garnalen','Een uitgebalanceerde low-FODMAP lunch voor 2 personen. glutenvrij.','lunch','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-020',true,2,23,E'120 g rijstnoedels — droog\n220 g garnalen — gepeld\n150 g komkommer — reepjes\n100 g wortel — reepjes\n20 g pinda’s — gehakt\n20 ml limoensap\n15 ml tamari\n10 g munt',E'1. Bereid noedels volgens verpakking en spoel koud.\n2. Bak garnalen gaar.\n3. Meng limoensap en tamari.\n4. Schep alles om en bestrooi met pinda en munt.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Citroen-kruidenkip met aardappelen','Een smaakvol low-FODMAP hoofdgerecht voor 4 personen. glutenvrij, meal-prep.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-021',true,4,50,E'600 g kipdijfilet\n800 g aardappelen — partjes\n400 g wortelen — stukken\n1 stuk citroen — sap en rasp\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\n5 g gedroogde oregano\nnaar smaak  zout en zwarte peper',E'1. Verwarm de oven voor op 200 °C.\n2. Meng aardappel en wortel met olie, oregano, zout en peper; rooster 15 minuten.\n3. Voeg kip toe, besprenkel met citroen en rooster nog 20 minuten tot gaar.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Zalm met rijst en sperziebonen','Een smaakvol low-FODMAP hoofdgerecht voor 2 personen. glutenvrij.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-022',true,2,30,E'300 g zalmfilet\n300 g gekookte rijst\n200 g sperziebonen\n15 ml citroensap\n10 g dille\n15 ml olijfolie\nnaar smaak  zout en zwarte peper',E'1. Verwarm de oven voor op 190 °C.\n2. Besprenkel zalm met olie, citroen, dille, zout en peper.\n3. Bak 15–18 minuten.\n4. Serveer met warme rijst en gestoomde bonen.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Kalkoenballetjes met glutenvrije pasta','Een smaakvol low-FODMAP hoofdgerecht voor 4 personen. glutenvrij, meal-prep.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-023',true,4,45,E'500 g kalkoengehakt\n1 stuk ei\n30 g glutenvrij paneermeel — zonder inuline\n15 g bieslook\n500 ml passata — zonder ui/knoflook\n300 g glutenvrije pasta — droog\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\n5 g gedroogde basilicum\nnaar smaak  zout en zwarte peper',E'1. Meng gehakt, ei, paneermeel, bieslook, zout en peper en vorm 16 balletjes.\n2. Bak de balletjes in olie rondom bruin.\n3. Voeg passata en basilicum toe en laat 15 minuten sudderen.\n4. Kook pasta en serveer 4 balletjes per persoon.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Rundvleesroerbak met rijst','Een smaakvol low-FODMAP hoofdgerecht voor 2 personen. glutenvrij.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-024',true,2,25,E'300 g biefstukreepjes\n300 g gekookte rijst\n100 g wortel — reepjes\n200 g paksoi — in stukken\n20 ml tamari\n10 ml sesamolie\n10 g verse gember',E'1. Roerbak rundvlees kort en heet in sesamolie en neem uit de pan.\n2. Bak wortel, paksoi en gember 4 minuten.\n3. Voeg vlees en tamari toe en warm door.\n4. Serveer met rijst.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Krokante tofu met pindasaus','Een smaakvol low-FODMAP hoofdgerecht voor 2 personen. vegan, glutenvrij.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-025',true,2,40,E'300 g stevige tofu\n20 g maïzena\n300 g gekookte rijst\n120 g wortel\n150 g komkommer\n30 g pindakaas — 100% pinda\n15 ml tamari\n15 ml limoensap\n30 ml water',E'1. Dep tofu droog, meng met maïzena en bak goudbruin.\n2. Roer pindakaas, tamari, limoen en water glad.\n3. Verdeel rijst en groenten over kommen.\n4. Voeg tofu toe en geef de saus erbij.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Garnalentaco’s met limoenslaw','Een smaakvol low-FODMAP hoofdgerecht voor 2 personen. glutenvrij.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-026',true,2,30,E'6 klein maïstortilla’s — zonder tarwe/inuline\n250 g garnalen\n120 g rode kool — fijn gesneden\n80 g wortel — geraspt\n60 g lactosevrije yoghurt\n20 ml limoensap\n10 g bieslook\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\nnaar smaak  zout en zwarte peper',E'1. Meng kool, wortel, yoghurt, limoen en bieslook.\n2. Bak garnalen 3–4 minuten in olie.\n3. Verwarm tortilla’s.\n4. Vul elke tortilla met slaw en garnalen; 3 per persoon.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Kabeljauwtraybake met tomaat','Een smaakvol low-FODMAP hoofdgerecht voor 2 personen. glutenvrij.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-027',true,2,40,E'300 g kabeljauwfilet\n400 g aardappelen — kleine blokjes\n150 g tomaat — partjes\n120 g courgette — plakjes; 60 g per persoon\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\n15 g peterselie\nnaar smaak  zout en zwarte peper',E'1. Verwarm oven voor op 200 °C.\n2. Rooster aardappel met olie 15 minuten.\n3. Voeg kabeljauw, tomaat en courgette toe en rooster 10–12 minuten.\n4. Bestrooi met peterselie.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Kip-quinoabowl met citroendressing','Een smaakvol low-FODMAP hoofdgerecht voor 2 personen. glutenvrij, meal-prep.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-028',true,2,30,E'300 g kipfilet\n300 g gekookte quinoa\n150 g komkommer\n100 g wortel\n80 g babyspinazie\n20 ml citroensap\n20 ml olijfolie\nnaar smaak  zout en zwarte peper',E'1. Bak de kip gaar en snijd in repen.\n2. Verdeel quinoa en groenten over kommen.\n3. Klop olie, citroensap, zout en peper.\n4. Voeg kip toe en sprenkel dressing erover.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Runderburger met aardappelwedges','Een smaakvol low-FODMAP hoofdgerecht voor 2 personen. glutenvrij.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-029',true,2,45,E'300 g mager rundergehakt\n450 g aardappelen — partjes\n4 bladeren kropsla\n100 g tomaat — plakken\n10 g mosterd — zonder ui/knoflook\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\nnaar smaak  zout en zwarte peper',E'1. Verwarm oven voor op 210 °C en rooster aardappelpartjes met helft van olie 25–30 minuten.\n2. Vorm 2 burgers, kruid en bak gaar.\n3. Serveer in slabladeren met tomaat en mosterd.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Aardappel-courgettefrittata','Een smaakvol low-FODMAP hoofdgerecht voor 4 personen. vegetarisch, glutenvrij.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-030',true,4,45,E'8 stuks eieren\n400 g gekookte aardappel — plakjes\n240 g courgette — 60 g per portie\n80 g harde kaas — geraspt\n15 g bieslook\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\nnaar smaak  zout en zwarte peper',E'1. Verwarm oven voor op 180 °C.\n2. Bak courgette 3 minuten in ovenvaste pan.\n3. Voeg aardappel toe.\n4. Klop eieren met kaas, bieslook, zout en peper, giet erbij en bak 25 minuten.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Gevulde paprika met quinoa en kalkoen','Een smaakvol low-FODMAP hoofdgerecht voor 4 personen. glutenvrij, meal-prep.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-031',true,4,60,E'4 stuks groene paprika’s — gehalveerd\n400 g kalkoengehakt\n300 g gekookte quinoa\n250 ml passata — zonder ui/knoflook\n60 g harde kaas\n20 g groene deel lente-ui\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\nnaar smaak  zout en zwarte peper',E'1. Verwarm oven voor op 190 °C en zet paprikahalven in schaal.\n2. Bak kalkoen in olie en meng met quinoa, passata en lente-uigroen.\n3. Vul paprika’s en bestrooi met kaas.\n4. Bak 30–35 minuten.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Polenta met runderragù zonder ui','Een smaakvol low-FODMAP hoofdgerecht voor 4 personen. glutenvrij, meal-prep.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-032',true,4,50,E'500 g mager rundergehakt\n600 ml passata — zonder ui/knoflook\n150 g wortel — fijn geraspt\n200 g polenta — droog\n40 g Parmezaanse kaas\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\n5 g gedroogde oregano\nnaar smaak  zout en zwarte peper',E'1. Bak gehakt en wortel in olie.\n2. Voeg passata en oregano toe en laat 25 minuten sudderen.\n3. Kook polenta volgens verpakking.\n4. Serveer ragù over polenta met Parmezaan.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Kippensoep met rijstnoedels','Een smaakvol low-FODMAP hoofdgerecht voor 4 personen. glutenvrij, meal-prep.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-033',true,4,40,E'400 g kipfilet — blokjes\n160 g rijstnoedels — droog\n200 g wortelen — plakjes\n150 g babyspinazie\n1200 ml low-FODMAP bouillon — zonder ui/knoflook\n10 g verse gember\n25 g groene deel lente-ui',E'1. Breng bouillon met gember en wortel aan de kook.\n2. Voeg kip toe en kook 10 minuten.\n3. Voeg noedels toe volgens hun kooktijd.\n4. Roer spinazie erdoor en garneer met lente-uigroen.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Sesamzalm met rijstnoedels','Een smaakvol low-FODMAP hoofdgerecht voor 2 personen. glutenvrij.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-034',true,2,30,E'300 g zalmfilet\n120 g rijstnoedels — droog\n200 g paksoi\n20 ml tamari\n10 ml sesamolie\n10 g sesamzaad\n15 ml limoensap',E'1. Bereid noedels volgens verpakking.\n2. Bak zalm in de helft van de sesamolie.\n3. Roerbak paksoi in resterende olie.\n4. Meng noedels met tamari en limoen, voeg zalm, paksoi en sesam toe.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Biefstuk met aardappelpuree en wortel','Een smaakvol low-FODMAP hoofdgerecht voor 2 personen. glutenvrij.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-035',true,2,40,E'300 g biefstuk\n450 g aardappelen\n250 g wortelen\n60 ml lactosevrije melk\n20 g boter\nnaar smaak  zout en zwarte peper',E'1. Kook aardappel en wortel afzonderlijk gaar.\n2. Stamp aardappel met melk en boter.\n3. Bak biefstuk naar wens en laat 5 minuten rusten.\n4. Serveer met wortel en puree.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Tofu pad thai zonder ui en knoflook','Een smaakvol low-FODMAP hoofdgerecht voor 2 personen. vegan, glutenvrij.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-036',true,2,35,E'140 g rijstnoedels — droog\n250 g stevige tofu\n100 g wortel — reepjes\n180 g paksoi\n20 ml tamari\n20 ml limoensap\n10 ml pure ahornsiroop\n20 g pinda’s\n15 g groene deel lente-ui',E'1. Week of kook noedels volgens verpakking.\n2. Bak tofu goudbruin, voeg wortel en paksoi toe.\n3. Meng tamari, limoen en ahornsiroop en schep met noedels door de pan.\n4. Garneer met pinda en lente-uigroen.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Varkenshaas met rijst en spinazie','Een smaakvol low-FODMAP hoofdgerecht voor 2 personen. glutenvrij.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-037',true,2,30,E'300 g varkenshaas\n300 g gekookte rijst\n150 g babyspinazie\n10 g mosterd — zonder ui/knoflook\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\n3 g tijm\nnaar smaak  zout en zwarte peper',E'1. Bestrijk varkenshaas met mosterd, tijm, zout en peper.\n2. Bak rondom bruin in olie en gaar zachtjes door.\n3. Laat 5 minuten rusten en snijd.\n4. Laat spinazie slinken en serveer met rijst.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Milde kip-kokoscurry','Een smaakvol low-FODMAP hoofdgerecht voor 4 personen. glutenvrij, meal-prep.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-038',true,4,45,E'500 g kipfilet — blokjes\n250 g wortelen\n240 g courgette — 60 g per portie\n240 ml kokosmelk — 60 ml per portie\n250 ml passata — zonder ui/knoflook\n600 g gekookte rijst\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\n10 g kerriepoeder — zonder ui/knoflook\nnaar smaak  zout en zwarte peper',E'1. Bak kip in olie.\n2. Voeg wortel en kerriepoeder toe en bak 3 minuten.\n3. Voeg kokosmelk en passata toe en laat 15 minuten zacht koken.\n4. Voeg courgette de laatste 5 minuten toe en serveer met rijst.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Kalkoen-aardappelschotel met spinazie','Een smaakvol low-FODMAP hoofdgerecht voor 4 personen. glutenvrij, meal-prep.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-039',true,4,55,E'500 g kalkoengehakt\n700 g aardappelen — dunne plakjes\n200 g babyspinazie\n150 ml lactosevrije kookroom\n80 g harde kaas\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\nnaar smaak  zout en zwarte peper',E'1. Verwarm oven voor op 190 °C.\n2. Bak kalkoengehakt gaar en laat spinazie slinken.\n3. Leg met aardappel in lagen in een ovenschaal en giet room erover.\n4. Bestrooi met kaas en bak 30–35 minuten.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Ovenomelet met tomaat en feta','Een smaakvol low-FODMAP hoofdgerecht voor 4 personen. vegetarisch, glutenvrij.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-040',true,4,37,E'8 stuks eieren\n200 g tomaten — blokjes\n150 g babyspinazie\n80 g feta\n15 g bieslook\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\nnaar smaak  zout en zwarte peper',E'1. Verwarm oven voor op 180 °C.\n2. Laat spinazie slinken in een ingevette ovenschaal en voeg tomaat toe.\n3. Klop ei met bieslook, zout en peper en giet erover.\n4. Verkruimel feta erop en bak 22–25 minuten.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Geroosterde aardappelbowl met tofu','Een smaakvol low-FODMAP hoofdgerecht voor 2 personen. vegan, glutenvrij.','avondeten','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-041',true,2,45,E'450 g aardappelen — blokjes\n300 g stevige tofu\n150 g wortel\n100 g babyspinazie\n15 ml tamari\n15 ml knoflook-geïnfuseerde olijfolie — Smaak zonder stukjes knoflook; gebruik uitsluitend gefilterde olie\n5 g paprikapoeder\nnaar smaak  zout en zwarte peper',E'1. Verwarm oven voor op 210 °C.\n2. Rooster aardappel en wortel met olie en paprikapoeder 25 minuten.\n3. Bak tofu goudbruin en voeg tamari toe.\n4. Verdeel met spinazie over kommen.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Rijstwafels met pindakaas en banaan','Een eenvoudige low-FODMAP snack voor 1 persoon. vegan, glutenvrij.','tussendoor','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-042',true,1,3,E'2 stuks rijstwafels — naturel\n20 g pindakaas — 100% pinda\n40 g stevige banaan — in plakjes; gebruik niet overrijp\n1 snuf kaneel',E'1. Besmeer rijstwafels met pindakaas.\n2. Verdeel banaan erover en bestrooi met kaneel.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Lactosevrije yoghurt met aardbei','Een eenvoudige low-FODMAP snack voor 1 persoon. vegetarisch, glutenvrij.','tussendoor','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-043',true,1,3,E'150 g lactosevrije yoghurt\n75 g aardbeien\n10 g pompoenpitten',E'1. Schep yoghurt in een kom.\n2. Voeg aardbeien en pompoenpitten toe.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Sinaasappel met walnoten','Een eenvoudige low-FODMAP snack voor 1 persoon. vegan, glutenvrij.','tussendoor','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-044',true,1,3,E'1 middelgroot sinaasappel\n15 g walnoten',E'1. Pel de sinaasappel en verdeel in partjes.\n2. Eet samen met de walnoten.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Druiven met harde kaas','Een eenvoudige low-FODMAP snack voor 1 persoon. vegetarisch, glutenvrij.','tussendoor','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-045',true,1,3,E'80 g druiven\n30 g harde kaas — blokjes',E'1. Was en droog de druiven.\n2. Serveer met kaasblokjes.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Kruidenpopcorn','Een eenvoudige low-FODMAP snack voor 2 personen. vegan, glutenvrij.','tussendoor','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-046',true,2,13,E'60 g popcornmais\n10 ml olijfolie\n2 g gedroogde oregano\n1 snuf zout',E'1. Verhit olie in een pan met deksel.\n2. Pof de mais en schud regelmatig.\n3. Meng met oregano en zout en verdeel in 2 porties.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Havermout-blueberrymuffins','Een eenvoudige low-FODMAP snack voor 6 personen. vegetarisch, glutenvrij, meal-prep.','tussendoor','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-047',true,6,37,E'150 g havermoutmeel — gecertificeerd glutenvrij\n1 stuk ei\n150 ml lactosevrije melk\n120 g blauwe bessen — 20 g per muffin\n30 ml pure ahornsiroop\n6 g bakpoeder\n2 g kaneel',E'1. Verwarm oven voor op 180 °C.\n2. Meng droge ingrediënten en klop ei, melk en siroop apart.\n3. Meng kort en schep bessen erdoor.\n4. Verdeel over 6 vormen en bak 20–22 minuten; 1 muffin per portie.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Pindakaas-cacaoballetjes','Een eenvoudige low-FODMAP snack voor 8 personen. vegan, glutenvrij, meal-prep.','tussendoor','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-048',true,8,15,E'100 g havermout\n80 g pindakaas — 100% pinda\n30 ml pure ahornsiroop\n15 g cacaopoeder\n10 g chiazaad',E'1. Meng alle ingrediënten stevig.\n2. Koel 20 minuten.\n3. Vorm 8 gelijke balletjes; 1 balletje per portie.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Ananas-limoenijsjes','Een portiegebonden low-FODMAP dessert voor 6 personen. vegan, glutenvrij.','tussendoor','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-049',true,6,10,E'600 g verse ananas — 100 g per ijsje\n30 ml limoensap\n120 ml water\n15 ml pure ahornsiroop — optioneel',E'1. Pureer alles glad.\n2. Verdeel over 6 ijsvormen.\n3. Vries minimaal 6 uur in; 1 ijsje per portie.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Aardbeien met pure chocolade','Een portiegebonden low-FODMAP dessert voor 2 personen. vegetarisch, glutenvrij.','tussendoor','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-050',true,2,10,E'150 g aardbeien\n30 g pure chocolade — controleer melk en polyolen',E'1. Smelt chocolade voorzichtig.\n2. Doop aardbeien gedeeltelijk in chocolade.\n3. Laat kort opstijven; verdeel gelijk over 2 porties.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Kiwi-yoghurtijs','Een portiegebonden low-FODMAP dessert voor 4 personen. vegetarisch, glutenvrij.','tussendoor','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-051',true,4,10,E'4 stuks kiwi — 1 per portie\n300 g lactosevrije yoghurt\n20 ml pure ahornsiroop',E'1. Pureer kiwi met yoghurt en siroop.\n2. Verdeel over 4 ijsvormen.\n3. Vries minimaal 6 uur in.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true),
  ('Rijstpudding met kaneel','Een portiegebonden low-FODMAP dessert voor 4 personen. vegetarisch, glutenvrij.','tussendoor','Fodmap Tracker','https://fodmaptracker20.vercel.app/receptenboek/lf-052',true,4,40,E'400 g gekookte witte rijst\n500 ml lactosevrije melk\n30 g tafelsuiker\n3 g kaneel\n5 ml vanille-extract',E'1. Breng rijst, melk, suiker en vanille zacht aan de kook.\n2. Laat 25–30 minuten inkoken en roer regelmatig.\n3. Verdeel in 4 porties en bestrooi met kaneel.','Origineel Nederlandstalig recept uit het gecontroleerde Fodmap Tracker-receptenboek.','Ontworpen als low-FODMAP per opgegeven portie. Controleer merkproducten op ui/knoflook, inuline/cichoreiwortel, honing, fructose-fructosestroop en polyolen. Vergroot porties niet zonder actuele portiecontrole. Niet laboratoriumgetest of Monash-gecertificeerd; controleer actuele porties en producten in de Monash FODMAP-app en bespreek de eliminatiefase met een gespecialiseerde diëtist.',true)
